<script setup>
import {computed,inject,onBeforeUnmount,ref,watch} from 'vue';
import I from './Icon.vue';
import AssetPicker from './AssetPicker.vue';
import Modal from './Modal.vue';
import StoryModelSettings from './StoryModelSettings.vue';
import {call,mediaUrl} from '../api';
import {storyEditorValue,upstreamStoryText,storyShotProblems,storyPrimaryReferenceId,createStoryShot,createStoryAsset,storyKindLabel,storyUiDrafts,storyEpisodeFingerprint} from '../story-ui.mjs';
import '../story-studio.css';

const {state,draft,busy,workflowLocked,act,refresh,notify,navigate,registerDraftFlusher}=inject('studio');
const taskId=draft.value.id,cached=storyUiDrafts.get(taskId),initial=storyEditorValue(draft.value);
const story=ref(cached?.story||initial),tab=ref('episodes'),episodeId=ref(''),shotId=ref(''),assetId=ref(''),kind=ref('all'),error=ref(cached?'已恢复上次尚未保存的编辑，请保存后继续。':''),pending=ref(false),saving=ref(false),picker=ref(null),preview=ref(null),instructions=ref({}),inputFingerprint=ref('');
const baseline=ref(cached?.baseline||JSON.stringify(initial));
let saveRequest,saveTimer,fingerprintVersion=0;
const dirty=computed(()=>JSON.stringify(story.value)!==baseline.value);
const remoteStory=computed(()=>state.value?.drafts.find(item=>item.id===draft.value.id)?.story||draft.value.story);
const activeRun=computed(()=>state.value?.runs.some(run=>run.draftId===draft.value.id&&String(run.type).startsWith('story-')&&['running','queued','unknown'].includes(run.status)));
const locked=computed(()=>!!busy.value||workflowLocked.value||pending.value||saving.value||activeRun.value);
const episode=computed(()=>story.value.episodes.find(item=>item.id===episodeId.value)||story.value.episodes[0]);
const shot=computed(()=>episode.value?.shots.find(item=>item.id===shotId.value)||episode.value?.shots[0]);
const asset=computed(()=>story.value.assets.find(item=>item.id===assetId.value)||visibleAssets.value[0]);
const visibleAssets=computed(()=>story.value.assets.filter(item=>kind.value==='all'||item.kind===kind.value));
const upstream=computed(()=>upstreamStoryText(draft.value));
const sourceConfirmed=computed(()=>story.value.sourceMode==='custom'||draft.value.confirmed&&!!draft.value.finalText?.trim());
const sourceChanged=computed(()=>!sourceConfirmed.value||story.value.episodes.length>0&&((story.value.sourceMode!=='custom'&&story.value.sourceText!==upstream.value)||story.value.episodesSourceHash!==inputFingerprint.value));
const planningReady=computed(()=>sourceConfirmed.value&&story.value.episodes.length>0&&!sourceChanged.value);
const issues=computed(()=>storyShotProblems(shot.value,story.value.assets));
const localImage=computed(()=>(state.value.settings.provider.storyImageProtocol||'comfy')==='comfy');
const imageIssues=computed(()=>storyShotProblems(shot.value,story.value.assets,{imageProtocol:localImage.value?'comfy':'compatible'}));
const boundAssets=computed(()=>story.value.assets.filter(item=>shot.value?.assetIds.includes(item.id)));
const primaryReference=computed({get:()=>storyPrimaryReferenceId(shot.value),set:value=>{if(shot.value&&!locked.value)shot.value.primaryReferenceAssetId=value;}});
const videoIssues=computed(()=>storyShotProblems(shot.value,story.value.assets,{video:true}));
const composeReason=computed(()=>!episode.value?.shots.length?'请先拆分镜头':episode.value.shots.some(item=>!item.selectedVideoId)?'请为当前集的每个镜头选用有效视频后再合成':story.value.narrationMode==='upstream'&&!episode.value.narrationAssetId&&(story.value.episodes.length>1||!draft.value.voice.audioId)?'请选择当前集旁白音频后再合成':'');
const episodeSeconds=computed(()=>episode.value?.shots.reduce((sum,item)=>sum+(Number(item.duration)||0),0)||0);
const selectedNarration=computed(()=>state.value.assets.find(item=>item.id===episode.value?.narrationAssetId));
const instructionKey=computed(()=>tab.value==='assets'?asset.value?.id:shot.value?.id);
const correction=computed({get:()=>instructions.value[instructionKey.value]||'',set:value=>{if(instructionKey.value)instructions.value[instructionKey.value]=value;}});

function hydrate(value){story.value=storyEditorValue({...draft.value,story:value});baseline.value=JSON.stringify(story.value);storyUiDrafts.delete(taskId);}
watch(()=>draft.value.id,()=>{hydrate(draft.value.story);episodeId.value='';shotId.value='';assetId.value='';error.value='';});
watch(()=>remoteStory.value?.revision,()=>{if(!dirty.value&&!pending.value&&!saving.value)hydrate(remoteStory.value);});
watch(()=>episode.value?.id,()=>{shotId.value='';});
watch(()=>[kind.value,visibleAssets.value.map(item=>item.id).join(',')],()=>{if(!visibleAssets.value.some(item=>item.id===assetId.value))assetId.value=visibleAssets.value[0]?.id||'';});
watch(()=>[story.value.sourceText,story.value.episodeCount,story.value.episodeDuration],async()=>{const version=++fingerprintVersion;try{const value=await storyEpisodeFingerprint(story.value);if(version===fingerprintVersion)inputFingerprint.value=value;}catch{inputFingerprint.value='';}},{immediate:true});
watch(()=>JSON.stringify(story.value),()=>{clearTimeout(saveTimer);if(!dirty.value)return;storyUiDrafts.set(taskId,{story:JSON.parse(JSON.stringify(story.value)),baseline:baseline.value});if(!pending.value&&!saving.value&&!busy.value&&!workflowLocked.value)saveTimer=setTimeout(()=>persist().catch(e=>{error.value=e.message;}),1000);});

async function persist(){
  clearTimeout(saveTimer);
  if(saveRequest)return saveRequest;
  if(!dirty.value&&remoteStory.value)return {story:story.value};
  const snapshot=JSON.parse(JSON.stringify(story.value));saving.value=true;
  saveRequest=(async()=>{try{const result=await call('saveStory',{id:taskId,story:snapshot,revision:snapshot.revision});if(!result?.story)throw Error('服务器未返回已保存的非口播创作版本');if(draft.value.id===taskId)hydrate(result.story);else storyUiDrafts.delete(taskId);await refresh();return result;}catch(e){storyUiDrafts.set(taskId,{story:JSON.parse(JSON.stringify(story.value)),baseline:baseline.value});throw e;}finally{saving.value=false;saveRequest=null;}})();
  return saveRequest;
}
const unregister=registerDraftFlusher?.(async()=>{if(draft.value.id===taskId&&(dirty.value||saveRequest))await persist();});
onBeforeUnmount(()=>{clearTimeout(saveTimer);if(dirty.value||saveRequest)persist().catch(e=>notify('非口播编辑未能保存，已保留待恢复草稿：'+e.message,'error')).finally(()=>unregister?.());else unregister?.();});
async function run(action,payload={},label='保存非口播创作',nextTab){
  if(locked.value)return;
  const taskId=draft.value.id;pending.value=true;error.value='';let failure;
  try{
    const result=await act(label,async()=>{try{await persist();if(action==='saveStory')return{story:story.value};return await call(action,{id:taskId,...payload});}catch(e){failure=e;throw e;}});
    if(!result)throw failure||Error('操作未完成，请检查任务执行记录');
    if(draft.value.id!==taskId)return;
    if(result.story)hydrate(result.story);else{await refresh();hydrate(remoteStory.value);}
    if(nextTab)tab.value=nextTab;
    return result;
  }catch(e){error.value=e.message;}finally{pending.value=false;}
}
async function splitEpisodes(){
  if(story.value.sourceMode!=='custom')story.value.sourceText=upstream.value;
  if(!sourceConfirmed.value){error.value='请先在第二步确认最终文案，或切换为独立剧本';return;}
  if(!story.value.sourceText.trim()){error.value='请先填写非口播剧本';return;}
  if(!Number.isInteger(Number(story.value.episodeCount))||Number(story.value.episodeCount)<1){error.value='集数必须为正整数';return;}
  await run('splitStoryEpisodes',{},'按指定集数拆分剧本','episodes');
}
function assetPayload(){return{assetId:asset.value.id};}
function shotPayload(){return{episodeId:episode.value.id,shotId:shot.value.id};}
function addShot(){if(locked.value||!episode.value)return;const item=createStoryShot();episode.value.shots.push(item);shotId.value=item.id;}
function moveShot(offset){const list=episode.value.shots,index=list.findIndex(item=>item.id===shot.value.id),target=index+offset;if(locked.value||target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];}
function deleteShot(){if(locked.value||!shot.value)return;episode.value.shots=episode.value.shots.filter(item=>item.id!==shot.value.id);shotId.value='';}
function addAsset(){if(locked.value)return;const item=createStoryAsset(kind.value==='all'?'character':kind.value);story.value.assets.push(item);assetId.value=item.id;}
function removeAsset(){if(locked.value||!asset.value)return;const target=asset.value;if(story.value.episodes.some(item=>item.shots.some(s=>s.assetIds.includes(target.id)))){error.value='此资产仍被镜头引用，请先取消对应镜头的绑定再删除';return;}story.value.assets=story.value.assets.filter(item=>item.id!==target.id);assetId.value='';}
function setBinding(id,selected){if(!shot.value||locked.value)return;shot.value.assetIds=selected?[...new Set([...shot.value.assetIds,id])]:shot.value.assetIds.filter(value=>value!==id);if(!shot.value.assetIds.includes(shot.value.primaryReferenceAssetId))shot.value.primaryReferenceAssetId='';}
function chooseImage(target){picker.value={kind:'image',title:target.assetId?'为资产选用已有图片':'为镜头选用已有构图图',target};}
async function picked(item){const choice=picker.value;picker.value=null;if(!choice)return;if(choice.kind==='audio'){if(episode.value?.id===choice.episodeId)episode.value.narrationAssetId=item.id;return;}await run('selectStoryImage',{...choice.target,imageId:item.id},'选用已有图片');}
function describeCandidate(item){return item.status==='stale'?'输入已变化，历史版本':item.id===asset.value?.selectedImageId||item.id===shot.value?.selectedImageId||item.id===shot.value?.selectedVideoId?'已确认选用':'待确认';}
function candidateInstruction(item){return item.instruction||item.prompt||'未记录提示词';}
function episodeName(item,index){return '第 '+(index+1)+' 集 · '+(item.title||'未命名');}
function loadServer(){if(locked.value)return;hydrate(remoteStory.value);error.value='';notify('已载入服务器保存的非口播版本');}
</script>

<template>
  <section class="story-studio" aria-label="非口播创作工作台" :aria-busy="locked">
    <header class="story-intro card"><div><span class="story-eyebrow">STORY STUDIO</span><h3>非口播创作</h3><p>从前文拆集与分镜，确认人物、场景和道具，再生成镜头视频。当前集成片可继续剪辑、制作封面和发布。</p></div><button :disabled="locked" @click="navigate('settings')"><I name="Settings" :size="16"/>服务设置</button></header>
    <StoryModelSettings/>
    <p v-if="activeRun&&!busy" class="story-notice warning" role="status">当前非口播任务仍在执行或有远程结果待确认，请保留原任务，避免重复生成。<button @click="navigate('tasks')">进入任务中心查看 / 查询</button></p>
    <div class="story-toolbar"><div class="segmented story-tabs" role="tablist" aria-label="非口播制作阶段"><button v-for="item in [['episodes','分集分镜'],['assets','资产图片'],['videos','镜头视频']]" :key="item[0]" role="tab" :aria-selected="tab===item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]">{{item[1]}}</button></div><span class="story-save-state">{{dirty?'有未保存修改':'版本 '+story.revision+' · 已保存'}}</span><button :disabled="locked||!dirty" @click="run('saveStory')"><I name="Save" :size="16"/>保存修改</button></div>
    <p v-if="error" class="story-notice error" role="alert">{{error}}<button :disabled="locked" @click="loadServer">重新载入已保存版本</button></p>
    <p v-if="sourceChanged" class="story-notice warning" role="status">{{!sourceConfirmed?'前文尚未确认，已暂停生成、合成和交接。请先回到第二步确认最终文案；前文变化后需要重新拆集。':'剧本、指定集数或每集参考时长已变化；当前分集仍来自旧版本。请检查来源并重新拆集，再继续生成。'}}</p>

    <template v-if="tab==='episodes'">
      <article class="card story-source"><div class="card-heading"><h3>创作来源</h3><span>先保存要求，再按指定数量拆集</span></div><div class="story-fields story-source-options"><label>剧本来源<select v-model="story.sourceMode" :disabled="locked"><option value="upstream">使用前面步骤的最终文案</option><option value="custom">填写独立剧本</option></select></label><label>旁白方式<select v-model="story.narrationMode" :disabled="locked"><option value="none">无旁白，仅使用镜头声音设计</option><option value="upstream">使用第三步配音 / 每集指定旁白</option></select></label></div><p class="story-help">{{story.sourceMode==='custom'?'独立剧本单独保存，不改写前面步骤的最终文案。':sourceConfirmed?'已关联第二步确认文案；前文变化时会要求重新拆集。':'当前文案尚未确认，请先在第二步确认后拆集。'}}</p><label class="story-script-label">{{story.sourceMode==='custom'?'非口播剧本':'已关联文案'}}<textarea :value="story.sourceMode==='custom'?story.sourceText:upstream" :readonly="story.sourceMode!=='custom'" :disabled="locked" aria-label="非口播剧本" placeholder="填写需要拆分的故事、科普或产品短片文案" @input="story.sourceText=$event.target.value"/></label><div class="story-fields story-generation-options"><label>指定集数<input v-model.number="story.episodeCount" type="number" min="1" step="1" :disabled="locked" aria-label="指定集数"/></label><label>每集参考秒数<input v-model.number="story.episodeDuration" type="number" min="1" step="1" :disabled="locked" aria-label="每集参考秒数"/></label><label>画幅<select v-model="story.aspect" :disabled="locked"><option value="9:16">9:16 竖屏</option><option value="16:9">16:9 横屏</option><option value="1:1">1:1 方形</option></select></label><label>视觉风格<input v-model="story.style" :disabled="locked" placeholder="例如：自然写实、电影质感"/></label></div><label>补充要求<textarea v-model="story.instructions" class="story-brief" :disabled="locked" placeholder="主体、时代、节奏和需要避免的内容；事实类请提供可靠依据"/></label><div class="story-action-row"><p class="story-help">拆分后可逐集编辑；重新拆分会更新分集，请先保存需要保留的修改。</p><button class="primary" :disabled="locked||!sourceConfirmed" @click="splitEpisodes"><I name="Layers" :size="17"/>{{story.episodes.length?'按当前要求重新拆集':'按指定集数拆集'}}</button></div></article>
      <div v-if="story.episodes.length" class="story-workspace"><aside class="card story-episode-nav"><h3>分集列表</h3><button v-for="(item,index) in story.episodes" :key="item.id" :class="{active:episode?.id===item.id}" @click="episodeId=item.id"><strong>{{episodeName(item,index)}}</strong><small>{{item.shots.length}} 个镜头{{item.resultId?' · 已有成片':''}}</small></button></aside><article v-if="episode" class="card story-episode-editor"><div class="card-heading"><h3>当前集剧本与分镜</h3><span>{{episode.shots.length}} 镜头 · {{episodeSeconds.toFixed(1)}} 秒</span></div><label>本集标题<input v-model="episode.title" :disabled="locked" aria-label="本集标题"/></label><label>本集正文<textarea v-model="episode.text" :disabled="locked" aria-label="本集正文"/></label><div class="story-action-row"><button class="secondary" :disabled="locked||sourceChanged" @click="run('splitStoryShots',{episodeId:episode.id},'拆分当前集镜头')"><I name="Scissors" :size="16"/>{{episode.shots.length?'重新拆分镜头':'拆分当前集镜头'}}</button><button :disabled="locked" @click="addShot"><I name="Plus" :size="16"/>新增镜头</button><button :disabled="locked||!episode.shots.length||sourceChanged" @click="run('extractStoryAssets',{episodeId:episode.id},'提取当前集资产','assets')"><I name="Database" :size="16"/>提取本集资产</button></div><div v-if="episode.shots.length" class="story-shot-list" aria-label="本集镜头"><button v-for="(item,index) in episode.shots" :key="item.id" :class="{active:shot?.id===item.id}" @click="shotId=item.id"><strong>镜头 {{index+1}}</strong><span>{{item.visual||item.text||'待填写镜头'}}</span><small>{{item.duration}} 秒</small></button></div><section v-if="shot" class="story-shot-editor"><div class="card-heading"><h4>镜头详情</h4><div class="story-icon-actions"><button :disabled="locked||episode.shots[0].id===shot.id" aria-label="上移镜头" @click="moveShot(-1)"><I name="ChevronUp" :size="16"/></button><button :disabled="locked||episode.shots.at(-1).id===shot.id" aria-label="下移镜头" @click="moveShot(1)"><I name="ChevronDown" :size="16"/></button><button :disabled="locked" aria-label="删除当前镜头" @click="deleteShot"><I name="Trash2" :size="16"/></button></div></div><label>对应原文<textarea v-model="shot.text" :disabled="locked"/></label><div class="story-fields"><label>画面描述<textarea v-model="shot.visual" :disabled="locked"/></label><label>人物 / 主体动作<textarea v-model="shot.action" :disabled="locked"/></label><label>景别与运镜<input v-model="shot.camera" :disabled="locked" placeholder="例如：中景，缓慢推近"/></label><label>镜头时长（秒）<input v-model.number="shot.duration" type="number" min="0.1" step="0.1" :disabled="locked"/></label></div><label>镜头声音<textarea v-model="shot.sound" class="story-brief" :disabled="locked" placeholder="环境音、音效或对白要求"/></label><fieldset class="story-bindings"><legend>绑定本镜头资产</legend><label v-for="item in story.assets" :key="item.id" class="story-checkbox"><input type="checkbox" :checked="shot.assetIds.includes(item.id)" :disabled="locked" @change="setBinding(item.id,$event.target.checked)"/><span>{{storyKindLabel[item.kind]}} · {{item.name}}</span><small>{{item.selectedImageId?'图片已确认':'图片待确认'}}</small></label><p v-if="!story.assets.length" class="story-help">先提取本集资产，或前往“资产图片”添加人物、场景、道具。</p><template v-if="localImage&&boundAssets.length"><label>本地构图主参考<select v-model="primaryReference" :disabled="locked" aria-label="本地构图主参考"><option value="">请选择主参考资产</option><option v-for="item in boundAssets" :key="item.id" :value="item.id">{{storyKindLabel[item.kind]}} · {{item.name}}</option></select></label><p class="story-help">本地仅主参考图片参与图生图，其余绑定只传文字描述，不能保证多主体外观一致。</p></template><p v-else-if="!localImage&&boundAssets.length" class="story-help">云端兼容图片接口会提交全部已绑定资产的确认图片。</p></fieldset><details class="story-prompt-details"><summary>查看和编辑镜头提示词</summary><label>构图图提示词<textarea v-model="shot.imagePrompt" :disabled="locked"/></label><label>视频提示词<textarea v-model="shot.videoPrompt" :disabled="locked"/></label></details><div class="story-action-row"><p class="story-help">修改描述、动作或绑定后，保存会使受影响的选用结果失效，候选历史继续保留。</p><button :disabled="locked||!dirty" @click="run('saveStory')">保存镜头修改</button></div></section></article></div>
      <div v-else class="story-empty card"><I name="Layers" :size="34"/><h3>从当前文案开始拆集</h3><p>指定集数后生成分集，再逐集拆分镜头和提取共享资产。</p></div>
    </template>

    <template v-else-if="tab==='assets'">
      <p v-if="!story.episodes.length" class="story-notice warning">请先在“分集分镜”完成拆集，再生成或确认资产图片。资产设定可以提前填写并保存。</p>
      <div class="story-action-row story-section-actions"><div class="story-fields"><label>资产类型<select v-model="kind"><option value="all">全部资产</option><option value="character">人物</option><option value="scene">场景</option><option value="prop">道具</option></select></label><label>当前分集<select :value="episode?.id||''" @change="episodeId=$event.target.value"><option v-if="!story.episodes.length" value="">尚未拆集</option><option v-for="(item,index) in story.episodes" :key="item.id" :value="item.id">{{episodeName(item,index)}}</option></select></label></div><button :disabled="locked" @click="addAsset"><I name="Plus" :size="16"/>添加资产</button><button :disabled="locked||!episode?.shots.length||sourceChanged" @click="run('extractStoryAssets',{episodeId:episode.id},'提取当前集资产')">提取本集资产</button></div>
      <div v-if="asset" class="story-workspace story-assets-workspace"><aside class="card story-asset-nav"><h3>共享资产 · {{visibleAssets.length}}</h3><button v-for="item in visibleAssets" :key="item.id" :class="{active:asset.id===item.id}" @click="assetId=item.id"><img v-if="item.selectedImageId" :src="mediaUrl(item.selectedImageId)" alt="已确认资产图"/><I v-else :name="item.kind==='character'?'User':item.kind==='scene'?'House':'Layers'" :size="26"/><span><strong>{{item.name}}</strong><small>{{storyKindLabel[item.kind]}} · {{item.selectedImageId?'已确认图片':'待确认图片'}}</small></span></button></aside><article class="card story-asset-editor"><div class="card-heading"><h3>资产设定</h3><button :disabled="locked" class="text-button danger" @click="removeAsset">删除资产</button></div><div class="story-fields"><label>名称<input v-model="asset.name" :disabled="locked" aria-label="资产名称"/></label><label>类型<select v-model="asset.kind" :disabled="locked"><option value="character">人物</option><option value="scene">场景</option><option value="prop">道具</option></select></label></div><label>外观与识别特征<textarea v-model="asset.description" :disabled="locked" placeholder="用于跨镜头复用的外观、服装、环境或材质特征"/></label><label>资产图片提示词<textarea v-model="asset.prompt" :disabled="locked"/></label><p class="story-help">共享资产通过稳定 ID 绑定镜头；生成图片只新增候选，需要手动确认。改设定或改选图片会影响引用该资产的镜头。</p><label>本次修改要求<textarea v-model="correction" class="story-brief" :disabled="locked" placeholder="例如：保留服装，将表情调整得更自然"/></label><div class="story-action-row"><button class="primary" :disabled="locked||!planningReady" @click="run('generateStoryImage',{...assetPayload(),instruction:correction},'生成资产图片')"><I name="ImagePlus" :size="17"/>{{asset.images.length?'按当前要求再生成':'生成资产图片'}}</button><button :disabled="locked||!planningReady" @click="chooseImage(assetPayload())"><I name="FolderOpen" :size="17"/>导入 / 选用已有图</button><button :disabled="locked||!dirty" @click="run('saveStory')">保存设定</button></div><div v-if="asset.images.length" class="story-candidates"><article v-for="(item,index) in asset.images" :key="item.id" class="story-candidate" :class="{selected:asset.selectedImageId===item.id,stale:item.status==='stale'}"><button class="story-candidate-preview" :aria-label="'预览资产候选 '+(index+1)" @click="preview={id:item.id,type:'image',title:asset.name+' · 候选 '+(index+1)}"><img :src="mediaUrl(item.id)" :alt="asset.name+' 候选 '+(index+1)" loading="lazy"/></button><div><strong>候选 {{index+1}}</strong><span class="story-status">{{describeCandidate(item)}}</span><details><summary>生成记录</summary><p>{{candidateInstruction(item)}}</p><small>{{item.createdAt}}</small></details><button :disabled="locked||item.status==='stale'||asset.selectedImageId===item.id" @click="run('selectStoryImage',{...assetPayload(),imageId:item.id},'确认资产图片')">{{asset.selectedImageId===item.id?'已选用':'确认选用此图'}}</button></div></article></div><div v-else class="story-inline-empty">尚无图片候选。可生成新图，或选择已有图片后确认。</div></article></div><div v-else class="story-empty card"><I name="Database" :size="34"/><h3>建立可复用的视觉资产</h3><p>从分镜提取人物、场景和道具，也可以手动添加。</p><button :disabled="locked" @click="addAsset">添加第一个资产</button></div>
    </template>

    <template v-else>
      <div class="story-fields story-video-selection"><label>当前分集<select :value="episode?.id||''" @change="episodeId=$event.target.value"><option v-if="!story.episodes.length" value="">尚未拆集</option><option v-for="(item,index) in story.episodes" :key="item.id" :value="item.id">{{episodeName(item,index)}}</option></select></label><label>当前镜头<select :value="shot?.id||''" @change="shotId=$event.target.value"><option v-if="!episode?.shots.length" value="">尚无镜头</option><option v-for="(item,index) in episode?.shots||[]" :key="item.id" :value="item.id">镜头 {{index+1}} · {{item.duration}} 秒</option></select></label></div>
      <div v-if="shot" class="story-video-grid"><article class="card story-frame-panel"><div class="card-heading"><h3>1 · 镜头构图图</h3><span>{{shot.duration}} 秒</span></div><p class="story-shot-description">{{shot.visual||shot.text||'请先补充镜头画面描述'}}</p><div class="story-bound-summary"><span v-for="id in shot.assetIds" :key="id">{{story.assets.find(item=>item.id===id)?.name||'缺失资产'}}</span></div><p v-if="localImage" class="story-help">本地仅主参考图片参与图生图，其余绑定只传文字描述，不能保证多主体外观一致。<template v-if="primaryReference">当前主参考：{{boundAssets.find(item=>item.id===primaryReference)?.name}}</template></p><p v-for="reason in imageIssues" :key="reason" class="story-notice warning">{{reason}}</p><div class="story-frame-preview"><img v-if="shot.selectedImageId" :src="mediaUrl(shot.selectedImageId)" alt="已确认的镜头构图图"/><div v-else><I name="Image" :size="36"/><p>尚未确认构图图</p></div></div><label>本次画面 / 视频修改要求<textarea v-model="correction" class="story-brief" :disabled="locked" placeholder="不改变已绑定资产的前提下，调整构图、动作或运镜"/></label><div class="story-action-row"><button class="primary" :disabled="locked||!!imageIssues.length||sourceChanged" :title="imageIssues.join('；')" @click="run('generateStoryImage',{...shotPayload(),instruction:correction},'生成镜头构图图')">{{shot.images.length?'重新生成构图图':'生成构图图'}}</button><button :disabled="locked||!!issues.length" @click="chooseImage(shotPayload())">选用已有构图图</button></div><div class="story-filmstrip"><article v-for="(item,index) in shot.images" :key="item.id" :class="{selected:shot.selectedImageId===item.id,stale:item.status==='stale'}"><button :aria-label="'预览镜头构图候选 '+(index+1)" @click="preview={id:item.id,type:'image',title:'镜头构图候选 '+(index+1)}"><img :src="mediaUrl(item.id)" :alt="'镜头构图候选 '+(index+1)" loading="lazy"/></button><span>{{describeCandidate(item)}}</span><button :disabled="locked||item.status==='stale'||shot.selectedImageId===item.id" @click="run('selectStoryImage',{...shotPayload(),imageId:item.id},'确认镜头构图图')">{{shot.selectedImageId===item.id?'已选用':'确认此图'}}</button></article></div></article><article class="card story-motion-panel"><div class="card-heading"><h3>2 · 镜头动态视频</h3><span>逐镜头生成并确认</span></div><p v-for="reason in videoIssues" :key="reason" class="story-notice warning">{{reason}}</p><div class="story-frame-preview"><video v-if="shot.selectedVideoId" :key="shot.selectedVideoId" :src="mediaUrl(shot.selectedVideoId)" controls preload="metadata"/><div v-else><I name="Video" :size="36"/><p>尚未选用动态视频</p></div></div><p class="story-help">动作：{{shot.action||'未填写'}}<br/>景别与运镜：{{shot.camera||'未填写'}}<br/>声音：{{shot.sound||'未填写'}}</p><button class="primary full" :disabled="locked||!!videoIssues.length||sourceChanged" :title="videoIssues.join('；')" @click="run('generateStoryVideo',{...shotPayload(),instruction:correction},'生成非口播镜头视频')">{{shot.videos.length?'按当前要求再生成视频':'生成镜头视频'}}</button><div v-if="shot.videos.length" class="story-video-candidates"><article v-for="(item,index) in shot.videos" :key="item.id" :class="{selected:shot.selectedVideoId===item.id,stale:item.status==='stale'}"><video :src="mediaUrl(item.id)" controls preload="metadata"/><div><strong>视频候选 {{index+1}}</strong><span>{{describeCandidate(item)}}</span><button :disabled="locked||item.status==='stale'||shot.selectedVideoId===item.id" @click="run('selectStoryVideo',{...shotPayload(),videoId:item.id},'确认镜头视频')">{{shot.selectedVideoId===item.id?'已选用':'选用此视频'}}</button></div></article></div><p v-else class="story-inline-empty">生成成功后在这里试听、预览并选择版本。</p></article></div><div v-else class="story-empty card"><I name="Video" :size="34"/><h3>先完成分镜与资产图片</h3><p>选定一个镜头后，依次确认构图图并生成动态视频。</p><button @click="tab='episodes'">返回分集分镜</button></div>
      <article v-if="episode" class="card story-composition"><div class="card-heading"><h3>3 · 合成当前集</h3><span>{{episode.shots.filter(item=>item.selectedVideoId).length}} / {{episode.shots.length}} 镜头已选用</span></div><p>仅合成当前集，顺序与“分集分镜”中的镜头一致。多集分别制作和导出。</p><div v-if="story.narrationMode==='upstream'" class="story-narration"><span>本集旁白：{{selectedNarration?.name||'未指定'}}</span><button :disabled="locked" @click="picker={kind:'audio',title:'选择当前集旁白',episodeId:episode.id}">选择本集音频</button><button v-if="draft.voice.audioId&&story.episodes.length===1" :disabled="locked" @click="episode.narrationAssetId=draft.voice.audioId">使用第三步配音</button><button v-if="episode.narrationAssetId" :disabled="locked" @click="episode.narrationAssetId=''">清除本集旁白</button><p class="story-help">多集需要逐集指定音频，不会把整条配音随意切分给不同集。</p></div><p v-if="composeReason" class="story-notice warning">{{composeReason}}</p><div v-if="episode.resultId" class="story-result"><video :key="episode.resultId" :src="mediaUrl(episode.resultId)" controls preload="metadata"/><span>当前集成片 · 请检查完整播放、声音与镜头连续性</span></div><div class="story-action-row"><button class="primary" :disabled="locked||!!composeReason||sourceChanged" :title="composeReason" @click="run('composeStoryEpisode',{episodeId:episode.id},'按镜头顺序合成当前集')">{{episode.resultId?'重新合成当前集':'合成当前集'}}</button><button :disabled="locked||!episode.resultId||sourceChanged" @click="run('useStoryEpisode',{episodeId:episode.id},'将当前集交接后续剪辑')"><I name="Scissors" :size="17"/>使用当前集，进入网感剪辑</button></div></article>
    </template>
    <AssetPicker v-if="picker" :kind="picker.kind" :title="picker.title" @close="picker=null" @select="picked"/>
    <Modal v-if="preview" :title="preview.title" wide variant="story-image-preview" @close="preview=null"><img class="story-large-image" :src="mediaUrl(preview.id)" :alt="preview.title"/></Modal>
  </section>
</template>
